changeSet.sql:
CREATE TABLE task_type (
    name VARCHAR(40) PRIMARY KEY,
    built_in BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
INSERT INTO task_type (name, built_in) VALUES
    ('reminder', true), ('write', true), ('sketch', true),
    ('edit', true), ('hone', true), ('puzzle', true),
    ('imagine', true), ('research', true), ('consolidate', true),
    ('organize', true), ('transcribe', true);

ALTER TABLE note ADD COLUMN task_type VARCHAR(40) NOT NULL DEFAULT 'reminder'
    REFERENCES task_type(name);
ALTER TABLE note ADD COLUMN impact VARCHAR(20) NOT NULL DEFAULT 'n/a'
    CHECK (impact IN ('n/a','sentence','chapter','novel','recurring'));
ALTER TABLE note ADD COLUMN blocked BOOLEAN NOT NULL DEFAULT false;

-- Old constraint must go FIRST — the value migration below
-- writes priorities it would reject (this bit prod: dev had no
-- prioritized rows when it ran, prod did).
ALTER TABLE note DROP CONSTRAINT chk_note_priority;

-- Pre-dimension tasks (any old priority) become 'organize' tasks.
UPDATE note SET task_type = 'organize' WHERE priority != 'none';
UPDATE note SET blocked = true, priority = 'can' WHERE priority = 'blocked';
UPDATE note SET priority = 'must'   WHERE priority = 'P0';
UPDATE note SET priority = 'should' WHERE priority = 'P1';
UPDATE note SET priority = 'would'  WHERE priority = 'P2';
UPDATE note SET priority = 'can'    WHERE priority = 'P3';
-- Tasks keep a real priority; reminders stay 'none' internally.
UPDATE note SET priority = 'can' WHERE task_type != 'reminder' AND priority = 'none';

ALTER TABLE note ADD CONSTRAINT chk_note_priority
    CHECK (priority IN ('none','can','would','should','must'));

ALTER TABLE note DROP COLUMN flagged;
